    const base = sorted.map(r => {
      const emp = byName.get(norm(r.employee));
      const start = r.schedStart || emp?.shiftStart || s.defaultShiftStart;
      const occurrence = !r.date ? '' : r.leftEarly ? 'Left Early' : !r.arrival ? 'Absent'
        : timeToMin(r.arrival) > timeToMin(start) ? 'Tardy' : 'On Time';
      const minutesLate = occurrence === 'Tardy' ? timeToMin(r.arrival) - timeToMin(start) : '';
      const key = [norm(r.employee), r.date, occurrence, r.arrival || '', r.leftEarly || ''].join('|');
      return { ...r, occurrence, minutesLate, key, facility: emp?.homeFacility || '' };
    });
    const keyTotal = new Map(), empDate = new Map(), seen = new Map();
    for (const r of base) {
      keyTotal.set(r.key, (keyTotal.get(r.key) || 0) + 1);
      const ed = norm(r.employee) + '|' + r.date; empDate.set(ed, (empDate.get(ed) || 0) + 1);
    }
    for (const r of base) {
      if (!r.date) { r.dataCheck = ''; continue; }
      const n = (seen.get(r.key) || 0) + 1; seen.set(r.key, n);
      r.dataCheck = n > 1 ? 'Duplicate' : empDate.get(norm(r.employee) + '|' + r.date) > keyTotal.get(r.key) ? 'Review' : '';
    }
