  const otIndividuals = [...indiv.values()].filter(e => e.reg > 0).map(e => ({ ...e, pct: e.ot / e.reg })).sort((a, z) => z.pct - a.pct);

  // Throughput
  const tpMonthly = months.map(m => { const rows = tp.filter(r => inMonth(r.weekEnding, m)); return { ...m, p6049: sum(rows.filter(r => String(r.building) === '6049'), r => r.total), t6021: sum(rows.filter(r => String(r.building) === '6021'), r => r.total), total: sum(rows, r => r.total) }; });
  const tpWeeks = [...new Set(tp.map(r => r.weekEnding))].sort();
  const latestWeek = tpWeeks.at(-1) || '';
  const latestWeekTotal = bb => sum(tp.filter(r => r.weekEnding === latestWeek && (bb === 'all' || String(r.building) === bb)), r => r.total);
  const tpByCustomer = groupSum(tp, r => r.customer, r => r.total);

